export function DashboardTransactions() {
  return (
    <div className="panel">
      <div className="panel-title">Transaction History</div>
      <table className="market-table small-table">
        <thead><tr><th>ID</th><th>Date</th><th>Type</th><th>Asset</th><th>Amount</th><th>Status</th></tr></thead>
        <tbody>
          {transactionRows.map((row) => (
            <tr key={row.id}>
              <td><Link to={`/dashboard/transactions/${row.id}`}>{row.id}</Link></td>
              <td>{row.date}</td>
              <td>{row.type}</td>
              <td>{row.asset}</td>
              <td>{row.amount}</td>
              <td>{row.status}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export function DashboardTransactionDetails() {
  const { transactionId } = useParams();
  const transaction = transactionRows.find((row) => row.id === transactionId) ?? transactionRows[0];

  return (
    <div className="panel">
      <div className="panel-title">Transaction Details</div>
      <div className="review-list">
        <div><span>Transaction ID</span><strong>{transaction.id}</strong></div>
        <div><span>Date</span><strong>{transaction.date}</strong></div>
        <div><span>Type</span><strong>{transaction.type}</strong></div>
        <div><span>Asset</span><strong>{transaction.asset}</strong></div>
        <div><span>Amount</span><strong>{transaction.amount}</strong></div>
        <div><span>Rate</span><strong>{transaction.rate}</strong></div>
        <div><span>Fees</span><strong>{transaction.fees}</strong></div>
        <div><span>Status</span><strong>{transaction.status}</strong></div>
      </div>
    </div>
  );
}

