import { Link, NavLink, Outlet, useNavigate } from 'react-router-dom';
import { currencies, publicNav } from '../data';
import { useMarket } from '../context/MarketContext';

export default function PublicLayout() {
  const { currency, setCurrency, language, setLanguage } = useMarket();
  const navigate = useNavigate();

  return (
    <div className="app-shell">
      <header className="topbar">
        <div className="container topbar-inner">
          <Link className="brand" to="/">
            <span className="brand-mark">A</span>
            <span>AR-EXCHANGE</span>
          </Link>

          <nav className="main-nav" aria-label="Main navigation">
            {publicNav.map((item) => (
              <NavLink key={item.path} to={item.path} end={item.path === '/'} className={({ isActive }) => (isActive ? 'nav-link active' : 'nav-link')}>
                {item.label}
              </NavLink>
            ))}
          </nav>

          <div className="header-actions">
            <select aria-label="Language" value={language} onChange={(e) => setLanguage(e.target.value)}>
              <option value="EN">EN</option>
              <option value="FR">FR</option>
              <option value="PT">PT</option>
            </select>
            <select aria-label="Currency" value={currency} onChange={(e) => setCurrency(e.target.value)}>
              {currencies.map((code) => (
                <option key={code} value={code}>{code}</option>
              ))}
            </select>
            <button className="ghost-button" onClick={() => navigate('/login')}>Login</button>
            <button className="primary-button" onClick={() => navigate('/register')}>Create Account</button>
          </div>
        </div>
      </header>

      <main>
        <Outlet />
      </main>

      <footer className="site-footer">
        <div className="container footer-grid">
          <div>
            <div className="footer-brand">AR-EXCHANGE</div>
            <p>Secure digital asset trading built for Africa.</p>
          </div>
          <div>
            <h4>Products</h4>
            <ul>
              <li><Link to="/buy">Buy Crypto</Link></li>
              <li><Link to="/sell">Sell Crypto</Link></li>
              <li><Link to="/swap">Swap</Link></li>
              <li><Link to="/gift-cards">Gift Cards</Link></li>
              <li><Link to="/prices">Prices</Link></li>
            </ul>
          </div>
          <div>
            <h4>Company</h4>
            <ul>
              <li><Link to="/about">About</Link></li>
              <li><Link to="/how-it-works">How It Works</Link></li>
              <li><Link to="/blog">Blog</Link></li>
              <li><Link to="/careers">Careers</Link></li>
              <li><Link to="/affiliate">Affiliate</Link></li>
            </ul>
          </div>
          <div>
            <h4>Support</h4>
            <ul>
              <li><Link to="/faq">FAQ</Link></li>
              <li><Link to="/support">Help Center</Link></li>
              <li><Link to="/contact">Contact</Link></li>
              <li><Link to="/tracking">Track Order</Link></li>
            </ul>
          </div>
          <div>
            <h4>Legal</h4>
            <ul>
              <li><Link to="/legal/terms">Terms</Link></li>
              <li><Link to="/legal/privacy">Privacy</Link></li>
              <li><Link to="/legal/risk">Risk Disclosure</Link></li>
              <li><Link to="/legal/kyc-aml">KYC/AML</Link></li>
              <li><Link to="/legal/refund">Refund Policy</Link></li>
            </ul>
          </div>
        </div>
        <div className="container footer-meta">
          <span>\u00A9 2026 AR-EXCHANGE. All rights reserved.</span>
          <div className="socials">
            <span>Facebook</span>
            <span>Instagram</span>
            <span>X</span>
            <span>Telegram</span>
            <span>WhatsApp</span>
          </div>
        </div>
      </footer>

      <div className="mobile-bottom-nav">
        <Link to="/">Home</Link>
        <Link to="/prices">Markets</Link>
        <Link to="/buy">Trade</Link>
        <Link to="/dashboard/orders">Orders</Link>
        <Link to="/dashboard">Account</Link>
      </div>
    </div>
  );
}
