import { useParams } from 'react-router-dom';
import { legalContent } from '../data';

export default function LegalPage() {
  const { slug } = useParams();
  const current = (slug && legalContent[slug]) || legalContent.terms;

  return (
    <div className="container page-shell narrow-shell">
      <div className="page-head"><span className="eyebrow small">Legal</span><h1>{current.title}</h1></div>
      <div className="panel legal-panel"><p>{current.content}</p></div>
    </div>
  );
}
