import React from 'react';
import { useNavigate } from 'react-router-dom';
import { adminSummaryStats, orderRows, transactionRows, walletRows } from '../data';
import { useAdminAuth } from '../layouts/AdminLayout';

export function AdminLogin() {
  const { signIn } = useAdminAuth();
  const navigate = useNavigate();

  return (
    <div className="container page-shell narrow-shell auth-shell">
      <div className="panel auth-panel">
        <div className="panel-title">Admin Login</div>
        <div className="stacked-field"><label>Email</label><input type="email" placeholder="admin@ar-exchange.com" /></div>
        <div className="stacked-field"><label>Password</label><input type="password" placeholder="\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022" /></div>
        <div className="stacked-field"><label>2FA code</label><input type="text" placeholder="123456" /></div>
        <button
          className="primary-button full"
          onClick={() => {
            signIn();
            navigate('/admin');
          }}
        >
          Login to Admin
        </button>
      </div>
    </div>
  );
}

export function AdminDashboard() {
  return (
    <>
      <div className="dashboard-header"><h1>Admin Dashboard</h1><span>Super Admin</span></div>
      <div className="stats-grid">
        {adminSummaryStats.map((stat) => (
          <div className="stat-card" key={stat.label}><span>{stat.label}</span><strong>{stat.value}</strong></div>
        ))}
      </div>
      <div className="panel">
        <div className="panel-title">System alerts</div>
        <ul className="bullet-list">
          <li>2 new KYC review requests require attention.</li>
          <li>One withdrawal was flagged for manual review.</li>
          <li>Fee configuration changes are waiting for approval.</li>
        </ul>
      </div>
    </>
  );
}

type Column = { key: string; label: string };

function AdminTable({ title, columns, rows }: { title: string; columns: Column[]; rows: Record<string, React.ReactNode>[] }) {
  return (
    <div className="panel">
      <div className="panel-title">{title}</div>
      <table className="market-table small-table">
        <thead>
          <tr>{columns.map((col) => <th key={col.key}>{col.label}</th>)}</tr>
        </thead>
        <tbody>
          {rows.map((row, index) => (
            <tr key={index}>{columns.map((col) => <td key={col.key}>{row[col.key]}</td>)}</tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

