import React, { createContext, useContext, useState } from 'react';
import { Navigate, NavLink, Outlet } from 'react-router-dom';
import { adminNav } from '../data';

type AdminAuthValue = {
  isAdminSignedIn: boolean;
  signIn: () => void;
  signOut: () => void;
};

const AdminAuthContext = createContext<AdminAuthValue | undefined>(undefined);

export function AdminAuthProvider({ children }: { children: React.ReactNode }) {
  const [isAdminSignedIn, setIsAdminSignedIn] = useState(false);
  return (
    <AdminAuthContext.Provider
      value={{
        isAdminSignedIn,
        signIn: () => setIsAdminSignedIn(true),
        signOut: () => setIsAdminSignedIn(false),
      }}
    >
      {children}
    </AdminAuthContext.Provider>
  );
}

export function useAdminAuth() {
  const context = useContext(AdminAuthContext);
  if (!context) throw new Error('useAdminAuth must be used within an AdminAuthProvider');
  return context;
}

export default function AdminLayout() {
  const { isAdminSignedIn } = useAdminAuth();

  if (!isAdminSignedIn) {
    return <Navigate to="/admin/login" replace />;
  }

  return (
    <div className="container dashboard-shell">
      <aside className="dashboard-sidebar admin-sidebar">
        <div className="dashboard-brand">AR-ADMIN</div>
        <nav className="dashboard-nav">
          {adminNav.map((item) => (
            <NavLink key={item.path} to={item.path} end={item.path === '/admin'} className={({ isActive }) => (isActive ? 'dash-link active' : 'dash-link')}>
              {item.label}
            </NavLink>
          ))}
        </nav>
      </aside>
      <main className="dashboard-main">
        <Outlet />
      </main>
    </div>
  );
}
