import { Link, useNavigate } from 'react-router-dom';

export function Login() {
  const navigate = useNavigate();
  return (
    <div className="container page-shell narrow-shell auth-shell">
      <div className="panel auth-panel">
        <div className="panel-title">Login</div>
        <div className="stacked-field"><label>Email</label><input type="email" placeholder="you@example.com" /></div>
        <div className="stacked-field"><label>Password</label><input type="password" placeholder="\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022" /></div>
        <div className="inline-row">
          <Link className="ghost-button" to="/forgot-password">Forgot Password</Link>
          <button className="primary-button" onClick={() => navigate('/dashboard')}>Login</button>
        </div>
        <Link className="text-button" to="/register">Create Account</Link>
      </div>
    </div>
  );
}

export function Register() {
  const navigate = useNavigate();
  return (
    <div className="container page-shell narrow-shell auth-shell">
      <div className="panel auth-panel">
        <div className="panel-title">Create Account</div>
        <div className="stacked-field"><label>Full Name</label><input type="text" placeholder="Your full name" /></div>
        <div className="stacked-field"><label>Email</label><input type="email" placeholder="you@example.com" /></div>
        <div className="stacked-field"><label>Phone</label><input type="tel" placeholder="+234..." /></div>
        <div className="stacked-field"><label>Country</label><select defaultValue="Nigeria"><option>Nigeria</option><option>Ghana</option><option>Kenya</option></select></div>
        <div className="stacked-field"><label>Password</label><input type="password" placeholder="********" /></div>
        <div className="stacked-field"><label>Confirm Password</label><input type="password" placeholder="********" /></div>
        <button className="primary-button full" onClick={() => navigate('/verify-email')}>Create Account</button>
        <Link className="text-button" to="/login">Already have an account? Login</Link>
      </div>
    </div>
  );
}

export function VerifyEmail() {
  const navigate = useNavigate();
  return (
    <div className="container page-shell narrow-shell auth-shell">
      <div className="panel auth-panel">
        <div className="panel-title">Verify Your Email</div>
        <p>We sent an email verification link to your inbox. Verify your email to complete onboarding.</p>
        <button className="primary-button full" onClick={() => navigate('/dashboard')}>Continue to dashboard</button>
      </div>
    </div>
  );
}

export function ForgotPassword() {
  const navigate = useNavigate();
  return (
    <div className="container page-shell narrow-shell auth-shell">
      <div className="panel auth-panel">
        <div className="panel-title">Forgot Password</div>
        <div className="stacked-field"><label>Email</label><input type="email" placeholder="you@example.com" /></div>
        <button className="primary-button full" onClick={() => navigate('/reset-password')}>Send Reset Link</button>
      </div>
    </div>
  );
}

export function ResetPassword() {
  const navigate = useNavigate();
  return (
    <div className="container page-shell narrow-shell auth-shell">
      <div className="panel auth-panel">
        <div className="panel-title">Reset Password</div>
        <div className="stacked-field"><label>New Password</label><input type="password" /></div>
        <div className="stacked-field"><label>Confirm Password</label><input type="password" /></div>
        <button className="primary-button full" onClick={() => navigate('/login')}>Reset Password</button>
      </div>
    </div>
  );
}

export function TwoFactor() {
  const navigate = useNavigate();
  return (
    <div className="container page-shell narrow-shell auth-shell">
      <div className="panel auth-panel">
        <div className="panel-title">Two-Factor Authentication</div>
        <div className="stacked-field"><label>Enter 6-digit code</label><input type="text" placeholder="123456" /></div>
        <button className="primary-button full" onClick={() => navigate('/dashboard')}>Verify</button>
      </div>
    </div>
  );
}

export function AccountVerification() {
  return (
    <div className="container page-shell narrow-shell auth-shell">
      <div className="panel auth-panel">
        <div className="panel-title">Account Verification</div>
        <p>Your account verification status: <strong>Under Review</strong>.</p>
        <Link className="ghost-button full" to="/dashboard/kyc">Go to KYC Verification</Link>
      </div>
    </div>
  );
}
