import { Link } from 'react-router-dom';

function StatusPage({ eyebrow, title, message }: { eyebrow: string; title: string; message: string }) {
  return (
    <div className="container page-shell narrow-shell">
      <div className="page-head"><span className="eyebrow small">{eyebrow}</span><h1>{title}</h1></div>
      <div className="panel error-panel">
        <p>{message}</p>
        <Link className="primary-button" to="/">Return Home</Link>
      </div>
    </div>
  );
}

export function NotFoundPage() {
  return <StatusPage eyebrow="Error" title="404 \u2014 Page not found" message="The page you're looking for doesn't exist or may have moved. Please check the URL or return to the home page." />;
}

export function ServerErrorPage() {
  return <StatusPage eyebrow="Error" title="500 \u2014 Server error" message="Something went wrong on our end. Please try again shortly or contact support if the issue continues." />;
}

export function PaymentFailedPage() {
  return <StatusPage eyebrow="Payment" title="Payment Failed" message="Your payment could not be confirmed. No funds have been debited without a verified provider confirmation. Please try again or contact support." />;
}

export function TransactionFailedPage() {
  return <StatusPage eyebrow="Transaction" title="Transaction Failed" message="This transaction could not be completed. Please review the details and try again, or contact support for assistance." />;
}

export function TransactionPendingPage() {
  return <StatusPage eyebrow="Transaction" title="Transaction Pending" message="Your transaction is awaiting confirmation. This page will update once processing completes." />;
}

export function KycRejectedPage() {
  return <StatusPage eyebrow="KYC" title="KYC Rejected" message="Your verification submission was not approved. Please review the requirements and resubmit your documents." />;
}

export function InsufficientBalancePage() {
  return <StatusPage eyebrow="Wallet" title="Insufficient Balance" message="You do not have enough balance to complete this transaction. Please fund your wallet and try again." />;
}

export function InvalidWalletPage() {
  return <StatusPage eyebrow="Wallet" title="Invalid Wallet Address" message="The wallet address provided is not valid for the selected network. Please double-check and try again." />;
}

export function InvalidNetworkPage() {
  return <StatusPage eyebrow="Network" title="Invalid Network" message="The selected network does not match the destination wallet. Sending funds on the wrong network may result in permanent loss." />;
}

export function MaintenancePage() {
  return <StatusPage eyebrow="Maintenance" title="Scheduled Maintenance" message="AR-EXCHANGE is currently undergoing scheduled maintenance. Please check back shortly." />;
}

export function NoTransactionsPage() {
  return <StatusPage eyebrow="Transactions" title="No Transactions Yet" message="You haven't made any transactions yet. Start by buying, selling or swapping an asset." />;
}

export function NoOrdersPage() {
  return <StatusPage eyebrow="Orders" title="No Orders Yet" message="You don't have any orders yet. Your buy, sell, swap and gift card orders will appear here." />;
}

export function NoNotificationsPage() {
  return <StatusPage eyebrow="Notifications" title="No Notifications" message="You're all caught up. New account and transaction notifications will appear here." />;
}

export function NoSupportTicketsPage() {
  return <StatusPage eyebrow="Support" title="No Support Tickets" message="You haven't opened any support tickets yet. Contact support if you need help." />;
}
