import { Route, Routes } from 'react-router-dom';
import './App.css';
import PublicLayout from './layouts/PublicLayout';
import DashboardLayout from './layouts/DashboardLayout';
import AdminLayout from './layouts/AdminLayout';
import {
  AboutUs,
  Affiliate,
  Blog,
  BlogArticle,
  BuyCrypto,
  Careers,
  Contact,
  CryptoDetails,
  Faq,
  Fees,
  GiftCardBuy,
  GiftCardSell,
  GiftCards,
  Home,
  HowItWorks,
  Prices,
  Referral,
  SellCrypto,
  Support,
  SwapCrypto,
  TrackOrder,
} from './pages/PublicPages';
import { AccountVerification, ForgotPassword, Login, Register, ResetPassword, TwoFactor, VerifyEmail } from './pages/AuthPages';
import {
  DashboardAccountSettings,
  DashboardApiSettings,
  DashboardBuy,
  DashboardDeposit,
  DashboardGiftCards,
  DashboardKyc,
  DashboardNotifications,
  DashboardOrders,
  DashboardOverview,
  DashboardProfile,
  DashboardReferral,
  DashboardSecurity,
  DashboardSell,
  DashboardSupportTickets,
  DashboardSwap,
  DashboardTransactionDetails,
  DashboardTransactions,
  DashboardWallets,
  DashboardWithdraw,
} from './pages/DashboardPages';
import LegalPage from './pages/LegalPages';
import { AdminAuthProvider } from './layouts/AdminLayout';
import {
  AdminAffiliates,
  AdminApiSettings,
  AdminBlog,
  AdminBuyOrders,
  AdminContent,
  AdminCrypto,
  AdminCustomers,
  AdminDashboard,
  AdminFees,
  AdminGiftCardManagement,
  AdminGiftCardOrders,
  AdminKyc,
  AdminLogin,
  AdminNotifications,
  AdminPayments,
  AdminRates,
  AdminReferrals,
  AdminReports,
  AdminRoles,
  AdminSecurityLogs,
  AdminSellOrders,
  AdminSettings,
  AdminSupport,
  AdminSwapOrders,
  AdminTransactions,
  AdminUsers,
  AdminWallets,
} from './pages/AdminPages';
import {
  InsufficientBalancePage,
  InvalidNetworkPage,
  InvalidWalletPage,
  KycRejectedPage,
  MaintenancePage,
  NoNotificationsPage,
  NoOrdersPage,
  NoSupportTicketsPage,
  NoTransactionsPage,
  NotFoundPage,
  PaymentFailedPage,
  ServerErrorPage,
  TransactionFailedPage,
  TransactionPendingPage,
} from './pages/StatusPages';
import { MarketProvider } from './context/MarketContext';

export default function App() {
  return (
    <MarketProvider>
      <AdminAuthProvider>
        <Routes>
          <Route element={<PublicLayout />}>
            <Route path="/" element={<Home />} />
            <Route path="/buy" element={<BuyCrypto />} />
            <Route path="/sell" element={<SellCrypto />} />
            <Route path="/swap" element={<SwapCrypto />} />
            <Route path="/gift-cards" element={<GiftCards />} />
            <Route path="/gift-cards/buy" element={<GiftCardBuy />} />
            <Route path="/gift-cards/sell" element={<GiftCardSell />} />
            <Route path="/prices" element={<Prices />} />
            <Route path="/crypto/:coinId" element={<CryptoDetails />} />
            <Route path="/about" element={<AboutUs />} />
            <Route path="/how-it-works" element={<HowItWorks />} />
            <Route path="/fees" element={<Fees />} />
            <Route path="/faq" element={<Faq />} />
            <Route path="/contact" element={<Contact />} />
            <Route path="/support" element={<Support />} />
            <Route path="/tracking" element={<TrackOrder />} />
            <Route path="/track" element={<TrackOrder />} />
            <Route path="/blog" element={<Blog />} />
            <Route path="/blog/:articleId" element={<BlogArticle />} />
            <Route path="/affiliate" element={<Affiliate />} />
            <Route path="/referral" element={<Referral />} />
            <Route path="/careers" element={<Careers />} />

            <Route path="/login" element={<Login />} />
            <Route path="/register" element={<Register />} />
            <Route path="/verify-email" element={<VerifyEmail />} />
            <Route path="/forgot-password" element={<ForgotPassword />} />
            <Route path="/reset-password" element={<ResetPassword />} />
            <Route path="/2fa" element={<TwoFactor />} />
            <Route path="/verify-account" element={<AccountVerification />} />

            <Route path="/legal/:slug" element={<LegalPage />} />

            <Route element={<DashboardLayout />}>
              <Route path="/dashboard" element={<DashboardOverview />} />
              <Route path="/dashboard/profile" element={<DashboardProfile />} />
              <Route path="/dashboard/security" element={<DashboardSecurity />} />
              <Route path="/dashboard/kyc" element={<DashboardKyc />} />
              <Route path="/dashboard/wallets" element={<DashboardWallets />} />
              <Route path="/dashboard/buy" element={<DashboardBuy />} />
              <Route path="/dashboard/sell" element={<DashboardSell />} />
              <Route path="/dashboard/swap" element={<DashboardSwap />} />
              <Route path="/dashboard/gift-cards" element={<DashboardGiftCards />} />
              <Route path="/dashboard/orders" element={<DashboardOrders />} />
              <Route path="/dashboard/transactions" element={<DashboardTransactions />} />
              <Route path="/dashboard/transactions/:transactionId" element={<DashboardTransactionDetails />} />
              <Route path="/dashboard/deposit" element={<DashboardDeposit />} />
              <Route path="/dashboard/withdraw" element={<DashboardWithdraw />} />
              <Route path="/dashboard/notifications" element={<DashboardNotifications />} />
              <Route path="/dashboard/support" element={<DashboardSupportTickets />} />
              <Route path="/dashboard/referral" element={<DashboardReferral />} />
              <Route path="/dashboard/api-settings" element={<DashboardApiSettings />} />
              <Route path="/dashboard/settings" element={<DashboardAccountSettings />} />
            </Route>

            <Route path="/errors/payment-failed" element={<PaymentFailedPage />} />
            <Route path="/errors/transaction-failed" element={<TransactionFailedPage />} />
            <Route path="/errors/transaction-pending" element={<TransactionPendingPage />} />
            <Route path="/errors/kyc-rejected" element={<KycRejectedPage />} />
            <Route path="/errors/insufficient-balance" element={<InsufficientBalancePage />} />
            <Route path="/errors/invalid-wallet" element={<InvalidWalletPage />} />
            <Route path="/errors/invalid-network" element={<InvalidNetworkPage />} />
            <Route path="/errors/maintenance" element={<MaintenancePage />} />
            <Route path="/errors/no-transactions" element={<NoTransactionsPage />} />
            <Route path="/errors/no-orders" element={<NoOrdersPage />} />
            <Route path="/errors/no-notifications" element={<NoNotificationsPage />} />
            <Route path="/errors/no-support-tickets" element={<NoSupportTicketsPage />} />
            <Route path="/500" element={<ServerErrorPage />} />
            <Route path="*" element={<NotFoundPage />} />
          </Route>

          <Route path="/admin/login" element={<AdminLogin />} />
          <Route path="/admin" element={<AdminLayout />}>
            <Route index element={<AdminDashboard />} />
            <Route path="customers" element={<AdminCustomers />} />
            <Route path="kyc" element={<AdminKyc />} />
            <Route path="orders/buy" element={<AdminBuyOrders />} />
            <Route path="orders/sell" element={<AdminSellOrders />} />
            <Route path="orders/swap" element={<AdminSwapOrders />} />
            <Route path="orders/gift-cards" element={<AdminGiftCardOrders />} />
            <Route path="transactions" element={<AdminTransactions />} />
            <Route path="payments" element={<AdminPayments />} />
            <Route path="wallets" element={<AdminWallets />} />
            <Route path="crypto" element={<AdminCrypto />} />
            <Route path="rates" element={<AdminRates />} />
            <Route path="fees" element={<AdminFees />} />
            <Route path="gift-cards" element={<AdminGiftCardManagement />} />
            <Route path="support" element={<AdminSupport />} />
            <Route path="notifications" element={<AdminNotifications />} />
            <Route path="referrals" element={<AdminReferrals />} />
            <Route path="affiliates" element={<AdminAffiliates />} />
            <Route path="blog" element={<AdminBlog />} />
            <Route path="content" element={<AdminContent />} />
            <Route path="users" element={<AdminUsers />} />
            <Route path="roles" element={<AdminRoles />} />
            <Route path="reports" element={<AdminReports />} />
            <Route path="settings" element={<AdminSettings />} />
            <Route path="api-settings" element={<AdminApiSettings />} />
            <Route path="security-logs" element={<AdminSecurityLogs />} />
          </Route>
        </Routes>
      </AdminAuthProvider>
    </MarketProvider>
  );
}
