import React, { createContext, useContext, useEffect, useMemo, useState } from 'react';
import { MarketCoin, fallbackCoins } from '../data';

type MarketContextValue = {
  marketData: MarketCoin[];
  currency: string;
  setCurrency: (value: string) => void;
  language: string;
  setLanguage: (value: string) => void;
};

const MarketContext = createContext<MarketContextValue | undefined>(undefined);

export function MarketProvider({ children }: { children: React.ReactNode }) {
  const [marketData, setMarketData] = useState<MarketCoin[]>(fallbackCoins);
  const [currency, setCurrency] = useState('NGN');
  const [language, setLanguage] = useState('EN');

  useEffect(() => {
    let active = true;
    const marketDataUrl = import.meta.env.VITE_MARKET_DATA_URL || 'https://api.coingecko.com/api/v3';
    fetch(`${marketDataUrl}/coins/markets?vs_currency=usd&ids=bitcoin,ethereum,tether,usd-coin,binancecoin,solana,tron,ripple,dogecoin&per_page=20&page=1&sparkline=false`)
      .then((response) => response.json())
      .then((data) => {
        if (!active || !Array.isArray(data)) return;
        setMarketData(data);
      })
      .catch(() => {
        setMarketData(fallbackCoins);
      });

    return () => {
      active = false;
    };
  }, []);

  const value = useMemo(
    () => ({ marketData, currency, setCurrency, language, setLanguage }),
    [marketData, currency, language],
  );

  return <MarketContext.Provider value={value}>{children}</MarketContext.Provider>;
}

export function useMarket() {
  const context = useContext(MarketContext);
  if (!context) throw new Error('useMarket must be used within a MarketProvider');
  return context;
}
