export function Prices() {
  const { marketData } = useMarket();
  const [marketQuery, setMarketQuery] = useState('');
  const [sortType, setSortType] = useState('market_cap');

  const marketSummary = useMemo(() => {
    const filtered = marketData.filter((coin) => coin.name.toLowerCase().includes(marketQuery.toLowerCase()) || coin.symbol.toLowerCase().includes(marketQuery.toLowerCase()));
    return [...filtered].sort((a, b) => {
      if (sortType === 'change') return b.price_change_percentage_24h - a.price_change_percentage_24h;
      if (sortType === 'volume') return b.total_volume - a.total_volume;
      return b.market_cap - a.market_cap;
    });
  }, [marketData, marketQuery, sortType]);

  return (
    <div className="container page-shell">
      <div className="page-head">
        <span className="eyebrow small">Crypto Prices</span>
        <h1>Market overview powered by live pricing feeds.</h1>
      </div>
      <div className="toolbar-row">
        <input type="text" placeholder="Search coin" value={marketQuery} onChange={(e) => setMarketQuery(e.target.value)} />
        <select value={sortType} onChange={(e) => setSortType(e.target.value)}>
          <option value="market_cap">Sort by market cap</option>
          <option value="change">Sort by 24H change</option>
          <option value="volume">Sort by volume</option>
        </select>
      </div>
      <div className="market-table-wrap">
        <table className="market-table">
          <thead>
            <tr>
              <th>Coin</th>
              <th>Price</th>
              <th>24H Change</th>
              <th>Market Cap</th>
              <th>Volume</th>
              <th>Buy</th>
              <th>Sell</th>
            </tr>
          </thead>
          <tbody>
            {marketSummary.map((coin) => (
              <tr key={coin.id}>
                <td className="coin-cell"><img src={coin.image} alt={coin.name} /><div><strong>{coin.name}</strong><small>{coin.symbol.toUpperCase()}</small></div></td>
                <td>{formatMoney(coin.current_price, 'USD', 2)}</td>
                <td className={coin.price_change_percentage_24h < 0 ? 'negative' : 'positive'}>{coin.price_change_percentage_24h.toFixed(2)}%</td>
                <td>{formatCompact(coin.market_cap)}</td>
                <td>{formatCompact(coin.total_volume)}</td>
                <td><Link className="tiny-button" to={`/buy?coin=${coin.id}`}>Buy</Link></td>
                <td><Link className="tiny-button alt" to={`/sell?coin=${coin.id}`}>Sell</Link></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

