export function TrackOrder() {
  const [orderId, setOrderId] = useState('');
  const [result, setResult] = useState<null | { status: string; type: string; date: string }>(null);

  const handleTrack = () => {
    if (!orderId.trim()) {
      setResult(null);
      return;
    }
    setResult({ status: 'Processing', type: 'Buy Order', date: '2026-09-22' });
  };

  return (
    <div className="container page-shell narrow-shell">
      <div className="page-head"><span className="eyebrow small">Track Order</span><h1>Look up your transaction status.</h1></div>
      <div className="panel">
        <div className="stacked-field">
          <label>Order ID or Transaction ID</label>
          <input type="text" placeholder="e.g. ARX-12894" value={orderId} onChange={(e) => setOrderId(e.target.value)} />
        </div>
        <button className="primary-button full" onClick={handleTrack}>Track Status</button>
        {result && (
          <div className="meta-grid" style={{ marginTop: 20 }}>
            <div><label>Order type</label><strong>{result.type}</strong></div>
            <div><label>Date</label><strong>{result.date}</strong></div>
            <div><label>Status</label><strong>{result.status}</strong></div>
          </div>
        )}
        {!result && orderId.trim() === '' && (
          <p style={{ marginTop: 16, color: 'var(--muted)' }}>Enter an order ID above, or view your full history from the dashboard <Link to="/dashboard/transactions">transaction history</Link>.</p>
        )}
      </div>
    </div>
  );
}

